-- hushmallow · production · RLS CHECK (run after ALL_MIGRATIONS.sql)
--
-- GENERATED by hushmallow/tools/auth/bundle-sql.mjs: supabase/tests/rls_check.sql, byte for byte, below.
-- Paste the whole file into a new query in the Supabase SQL editor and Run (role `postgres`). The
-- result is one column, rls_check: a PASS line per check, and the last line must read
--   ALL 35 CHECKS PASSED. Everything this script created was rolled back.
-- Nothing is left behind and no email is sent. Any FAIL: do not switch sign-in on (RUNBOOK.md).
-- hushmallow · Row Level Security check (read only in effect: everything is rolled back)
--
-- Paste the whole file into the Supabase SQL editor and run it, after the
-- migrations. It creates two throwaway accounts (…@example.invalid, never
-- emailed: rows are written straight into auth.users, Supabase Auth sends
-- nothing), acts as each of them exactly as the app would (role
-- `authenticated` + request.jwt.claims, the way PostgREST does), as an
-- anonymous visitor (role `anon`), and proves that nobody can read, create,
-- change or delete another account's rows. Then it rolls EVERYTHING back on
-- purpose (an exception caught below), so nothing is left behind, whatever
-- the editor does with transactions.
--
-- The result is one table: a PASS/FAIL line per check and a summary line.
-- Any FAIL: stop and do not open sign-in to real people.

do $rls$
declare
  a uuid := gen_random_uuid();
  b uuid := gen_random_uuid();
  report text[] := '{}';
  fails integer := 0;
  total integer := 0;
  n integer;
  ok boolean;
  state text;
  t text;
  claims_a text := json_build_object('sub', a, 'role', 'authenticated', 'aud', 'authenticated')::text;
  claims_b text := json_build_object('sub', b, 'role', 'authenticated', 'aud', 'authenticated')::text;
begin
  -- ------------------------------------------------------ static checks --
  foreach t in array array['profiles', 'sync_consents', 'preferences', 'favourite_worlds', 'garden_skills', 'hushflow_progress'] loop
    select c.relrowsecurity and c.relforcerowsecurity into ok
      from pg_class c join pg_namespace s on s.oid = c.relnamespace
     where s.nspname = 'public' and c.relname = t;
    ok := coalesce(ok, false);
    total := total + 1; if not ok then fails := fails + 1; end if;
    report := report || format('%s  %s: row level security enabled and forced', case when ok then 'PASS' else 'FAIL' end, t);
    ok := not (has_table_privilege('anon', format('public.%I', t), 'SELECT')
               or has_table_privilege('anon', format('public.%I', t), 'INSERT')
               or has_table_privilege('anon', format('public.%I', t), 'UPDATE')
               or has_table_privilege('anon', format('public.%I', t), 'DELETE'));
    total := total + 1; if not ok then fails := fails + 1; end if;
    report := report || format('%s  %s: anon has no table privileges', case when ok then 'PASS' else 'FAIL' end, t);
  end loop;

  select exists (select 1 from pg_proc p join pg_roles r on r.oid = p.proowner
                  where p.oid = 'hm_private.handle_new_user()'::regprocedure and (r.rolbypassrls or r.rolsuper))
     and exists (select 1 from pg_proc p join pg_roles r on r.oid = p.proowner
                  where p.oid = 'public.delete_my_account()'::regprocedure and (r.rolbypassrls or r.rolsuper))
    into ok;
  total := total + 1; if not ok then fails := fails + 1; end if;
  report := report || format('%s  the sign-up trigger and delete_my_account() are owned by a role that bypasses RLS (needed with FORCE RLS)', case when ok then 'PASS' else 'FAIL' end);

  ok := not has_function_privilege('anon', 'public.delete_my_account()', 'EXECUTE')
        and has_function_privilege('authenticated', 'public.delete_my_account()', 'EXECUTE');
  total := total + 1; if not ok then fails := fails + 1; end if;
  report := report || format('%s  delete_my_account(): authenticated may execute it, anon may not', case when ok then 'PASS' else 'FAIL' end);

  select count(*) into n
    from pg_proc p join pg_namespace s on s.oid = p.pronamespace
   where (s.nspname = 'hm_private' or (s.nspname = 'public' and p.proname = 'delete_my_account'))
     and not coalesce('search_path=""' = any (p.proconfig), false);
  ok := n = 0;
  total := total + 1; if not ok then fails := fails + 1; end if;
  report := report || format('%s  every hushmallow function pins search_path to '''' (%s without)', case when ok then 'PASS' else 'FAIL' end, n);

  -- ------------------------------------------- behaviour, rolled back --
  begin
    insert into auth.users (id, aud, role, email, raw_user_meta_data, raw_app_meta_data, created_at, updated_at)
    values (a, 'authenticated', 'authenticated', 'rls-check-a-' || left(a::text, 8) || '@example.invalid', '{"display_name":"Check A"}', '{}', now(), now()),
           (b, 'authenticated', 'authenticated', 'rls-check-b-' || left(b::text, 8) || '@example.invalid', '{"display_name":"Check B"}', '{}', now(), now());

    -- as A ------------------------------------------------------------
    perform set_config('request.jwt.claims', claims_a, true);
    execute 'set local role authenticated';

    select count(*) into n from public.profiles;
    ok := n = 1 and exists (select 1 from public.profiles where user_id = a and display_name = 'Check A');
    total := total + 1; if not ok then fails := fails + 1; end if;
    report := report || format('%s  A sees exactly one profile, its own, made by the sign-up trigger (%s visible)', case when ok then 'PASS' else 'FAIL' end, n);

    update public.profiles set display_name = 'Changed by A' where user_id = b;
    get diagnostics n = row_count;
    ok := n = 0;
    total := total + 1; if not ok then fails := fails + 1; end if;
    report := report || format('%s  A cannot change B''s profile (%s rows changed)', case when ok then 'PASS' else 'FAIL' end, n);

    begin
      insert into public.profiles (user_id, display_name) values (b, 'Forged by A');
      ok := false; state := 'inserted';
    exception when others then ok := sqlstate = '42501'; state := sqlstate;
    end;
    total := total + 1; if not ok then fails := fails + 1; end if;
    report := report || format('%s  A cannot create a profile for B (%s)', case when ok then 'PASS' else 'FAIL' end, state);

    begin
      update public.profiles set created_at = now() - interval '9 years' where user_id = a;
      ok := false; state := 'updated';
    exception when others then ok := sqlstate = '42501'; state := sqlstate;
    end;
    total := total + 1; if not ok then fails := fails + 1; end if;
    report := report || format('%s  A cannot rewrite server columns of its own profile (%s)', case when ok then 'PASS' else 'FAIL' end, state);

    begin
      insert into public.favourite_worlds (user_id, world_id) values (a, 'static-storm');
      ok := false; state := 'inserted';
    exception when others then ok := sqlstate = '42501'; state := sqlstate;
    end;
    total := total + 1; if not ok then fails := fails + 1; end if;
    report := report || format('%s  without consent nothing can be synced (%s)', case when ok then 'PASS' else 'FAIL' end, state);

    insert into public.sync_consents (user_id, library_sync, settings_sync) values (a, true, true);
    select count(*) into n from public.sync_consents where user_id = a and library_sync and library_sync_at is not null and settings_sync_at is not null;
    ok := n = 1;
    total := total + 1; if not ok then fails := fails + 1; end if;
    report := report || format('%s  consent is recorded with a server timestamp', case when ok then 'PASS' else 'FAIL' end);

    insert into public.favourite_worlds (user_id, world_id, position) values (a, 'static-storm', 0);
    insert into public.garden_skills (user_id, skill_id, saved_at, practised, mallow) values (a, 'slowing-down', now(), 1, 'glitzi');
    insert into public.hushflow_progress (user_id, world_id, idx, sequence, step, seed, saved_at) values (a, 'static-storm', 0, array['static-storm', 'luminous-ocean'], 0.4, 7, now());
    insert into public.preferences (user_id, sound, text_scale) values (a, false, 1.25);
    select count(*) into n from public.favourite_worlds;
    ok := n = 1;
    total := total + 1; if not ok then fails := fails + 1; end if;
    report := report || format('%s  with consent A can keep its favourites, garden, progress and settings', case when ok then 'PASS' else 'FAIL' end);

    begin
      insert into public.favourite_worlds (user_id, world_id) values (b, 'static-storm');
      ok := false; state := 'inserted';
    exception when others then ok := sqlstate = '42501'; state := sqlstate;
    end;
    total := total + 1; if not ok then fails := fails + 1; end if;
    report := report || format('%s  A cannot write rows for B (%s)', case when ok then 'PASS' else 'FAIL' end, state);

    begin
      insert into public.favourite_worlds (user_id, world_id) values (a, 'I feel so sad today');
      ok := false; state := 'inserted';
    exception when others then ok := sqlstate = '23514'; state := sqlstate;
    end;
    total := total + 1; if not ok then fails := fails + 1; end if;
    report := report || format('%s  free text is refused where only ids belong (%s)', case when ok then 'PASS' else 'FAIL' end, state);

    begin
      insert into public.hushflow_progress (user_id, world_id, sequence, saved_at) values (a, 'static-storm', array['my secret thought'], now())
        on conflict (user_id) do update set sequence = excluded.sequence;
      ok := false; state := 'inserted';
    exception when others then ok := sqlstate = '23514'; state := sqlstate;
    end;
    total := total + 1; if not ok then fails := fails + 1; end if;
    report := report || format('%s  free text is refused in the progress sequence (%s)', case when ok then 'PASS' else 'FAIL' end, state);

    -- the 64-row cap counts new rows only (0009): saving the same 64 again, as every sync does, works; a 65th does not
    begin
      insert into public.favourite_worlds (user_id, world_id, position)
        select a, 'cap-world-' || g, g from generate_series(1, 63) g;   -- 64 with static-storm
      insert into public.favourite_worlds (user_id, world_id, position)
        select a, w.world_id, w.position from public.favourite_worlds w where w.user_id = a
        on conflict (user_id, world_id) do update set position = excluded.position;
      select count(*) into n from public.favourite_worlds where user_id = a;
      ok := n = 64; state := format('%s kept, the same 64 saved again', n);
      begin
        insert into public.favourite_worlds (user_id, world_id) values (a, 'cap-world-65');
        ok := false; state := state || ', a 65th accepted';
      exception when others then ok := ok and sqlstate = '23514'; state := state || ', a 65th refused (' || sqlstate || ')';
      end;
      delete from public.favourite_worlds where user_id = a and world_id like 'cap-world-%';
    exception when others then ok := false; state := sqlstate || ' ' || sqlerrm;
    end;
    total := total + 1; if not ok then fails := fails + 1; end if;
    report := report || format('%s  at most 64 favourites: re-saving them all works, a 65th is refused (%s)', case when ok then 'PASS' else 'FAIL' end, state);

    -- as B ------------------------------------------------------------
    execute 'reset role';
    perform set_config('request.jwt.claims', claims_b, true);
    execute 'set local role authenticated';

    select (select count(*) from public.profiles where user_id <> b)
         + (select count(*) from public.sync_consents)
         + (select count(*) from public.preferences)
         + (select count(*) from public.favourite_worlds)
         + (select count(*) from public.garden_skills)
         + (select count(*) from public.hushflow_progress) into n;
    ok := n = 0;
    total := total + 1; if not ok then fails := fails + 1; end if;
    report := report || format('%s  B sees none of A''s rows in any table (%s visible)', case when ok then 'PASS' else 'FAIL' end, n);

    delete from public.favourite_worlds where user_id = a;
    get diagnostics n = row_count;
    ok := n = 0;
    delete from public.profiles where user_id = a;
    get diagnostics n = row_count;
    ok := ok and n = 0;
    update public.sync_consents set library_sync = false where user_id = a;
    get diagnostics n = row_count;
    ok := ok and n = 0;
    total := total + 1; if not ok then fails := fails + 1; end if;
    report := report || format('%s  B cannot delete or change A''s rows (0 rows touched)', case when ok then 'PASS' else 'FAIL' end);

    begin
      perform public.delete_my_account();   -- deletes B, never A
      ok := true; state := 'B deleted';
    exception when others then ok := false; state := sqlstate || ' ' || sqlerrm;
    end;
    total := total + 1; if not ok then fails := fails + 1; end if;
    report := report || format('%s  delete_my_account() as B (%s)', case when ok then 'PASS' else 'FAIL' end, state);

    -- anonymous -------------------------------------------------------
    execute 'reset role';
    perform set_config('request.jwt.claims', json_build_object('role', 'anon')::text, true);
    execute 'set local role anon';
    begin
      select count(*) into n from public.profiles;
      ok := false; state := n || ' rows';
    exception when others then ok := sqlstate = '42501'; state := sqlstate;
    end;
    total := total + 1; if not ok then fails := fails + 1; end if;
    report := report || format('%s  anon cannot read profiles (%s)', case when ok then 'PASS' else 'FAIL' end, state);
    begin
      perform public.delete_my_account();
      ok := false; state := 'ran';
    exception when others then ok := sqlstate = '42501'; state := sqlstate;
    end;
    total := total + 1; if not ok then fails := fails + 1; end if;
    report := report || format('%s  anon cannot call delete_my_account() (%s)', case when ok then 'PASS' else 'FAIL' end, state);

    -- back to A: still all there; withdraw; delete ------------------------
    execute 'reset role';
    perform set_config('request.jwt.claims', claims_a, true);
    execute 'set local role authenticated';

    select count(*) into n from public.favourite_worlds where user_id = a;
    ok := n = 1 and exists (select 1 from public.profiles where user_id = a);
    total := total + 1; if not ok then fails := fails + 1; end if;
    report := report || format('%s  A''s rows survived B''s attempts and B''s deletion', case when ok then 'PASS' else 'FAIL' end);

    update public.sync_consents set library_sync = false where user_id = a;
    select (select count(*) from public.favourite_worlds) + (select count(*) from public.garden_skills) + (select count(*) from public.hushflow_progress) into n;
    ok := n = 0 and exists (select 1 from public.sync_consents where user_id = a and library_withdrawn_at is not null) and exists (select 1 from public.preferences where user_id = a);
    total := total + 1; if not ok then fails := fails + 1; end if;
    report := report || format('%s  withdrawing library consent deletes favourites, garden and progress (settings kept)', case when ok then 'PASS' else 'FAIL' end);

    update public.sync_consents set settings_sync = false where user_id = a;
    select count(*) into n from public.preferences;
    ok := n = 0;
    total := total + 1; if not ok then fails := fails + 1; end if;
    report := report || format('%s  withdrawing settings consent deletes the synced settings', case when ok then 'PASS' else 'FAIL' end);

    perform public.delete_my_account();
    select (select count(*) from public.profiles) + (select count(*) from public.sync_consents) into n;
    ok := n = 0;
    execute 'reset role';
    ok := ok and not exists (select 1 from auth.users where id = a) and not exists (select 1 from auth.users where id = b);
    total := total + 1; if not ok then fails := fails + 1; end if;
    report := report || format('%s  delete_my_account() removes the caller''s rows and its auth.users row', case when ok then 'PASS' else 'FAIL' end);

    raise exception using errcode = 'P0001', message = 'hm_rls_check_rollback';
  exception
    when others then
      if sqlerrm <> 'hm_rls_check_rollback' then
        fails := fails + 1; total := total + 1;
        report := report || format('FAIL  the check stopped early: %s %s', sqlstate, sqlerrm);
      end if;
  end;

  report := report || case when fails = 0
    then format('ALL %s CHECKS PASSED. Everything this script created was rolled back.', total)
    else format('%s OF %s CHECKS FAILED. Do not open sign-in until this is fixed. (Everything was rolled back.)', fails, total) end;
  perform set_config('hm.rls_report', array_to_string(report, E'\n'), false);
end
$rls$;

select line as rls_check from unnest(string_to_array(current_setting('hm.rls_report'), E'\n')) with ordinality as r(line, n) order by n;
